books = {}
next_id = 1

def handle(method, path, body=None):
    global next_id
    parts = path.strip('/').split('/')
    if method == 'POST' and parts == ['books']:
        books[next_id] = body
        next_id += 1
        return (201, next_id - 1)
    if len(parts) == 2 and parts[0] == 'books':
        bid = int(parts[1])
        if method == 'GET':
            return (200, books[bid]) if bid in books else (404, None)
        if method == 'DELETE':
            if bid in books:
                del books[bid]
                return (204, None)
            return (404, None)
    return (400, None)

print(handle('POST', '/books', {'title': 'Dune'}))
print(handle('GET', '/books/1'))
print(handle('GET', '/books/9'))
print(handle('DELETE', '/books/1'))
