import hmac, hashlib

def sign(secret, body):
    return hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()

def verify(secret, body, signature):
    return hmac.compare_digest(sign(secret, body), signature)

sig = sign('whsec_demo', '{"order":42,"paid":true}')
print(verify('whsec_demo', '{"order":42,"paid":true}', sig))
print(verify('whsec_demo', '{"order":42,"paid":false}', sig))

VALID = {'t1': ['read'], 't2': ['read', 'write']}

def gateway(req):
    scopes = VALID.get(req['token'])
    if scopes is None:
        return 401
    if req['needs'] not in scopes:
        return 403
    if req['used'] >= req['limit']:
        return 429
    return 200

print(gateway({'token': None, 'needs': 'read', 'used': 0, 'limit': 5}))
print(gateway({'token': 't1', 'needs': 'write', 'used': 0, 'limit': 5}))
print(gateway({'token': 't2', 'needs': 'write', 'used': 5, 'limit': 5}))
print(gateway({'token': 't2', 'needs': 'write', 'used': 2, 'limit': 5}))

