TYPES = {'integer': int, 'number': (int, float), 'string': str}
schema = {'required': ['id', 'price'], 'props': {'id': 'integer', 'price': 'number', 'name': 'string'}}

def check(obj, schema):
    out = []
    for f in schema['required']:
        if f not in obj:
            out.append('missing:' + f)
    for f, t in schema['props'].items():
        if f in obj:
            v = obj[f]
            if isinstance(v, bool) or not isinstance(v, TYPES[t]):
                out.append('type:' + f)
    return sorted(out)

print(check({'id': 1, 'price': 9.99}, schema))
print(check({'id': 1, 'price': '9.99'}, schema))
print(check({'price': 5, 'name': 7}, schema))

