}}

def routes(spec):
    out = []
    for path, methods in spec['paths'].items():
        for m, op in methods.items():
            ok = sorted(c for c in op['responses'] if c.startswith('2'))[0]
            out.append(m.upper() + ' ' + path + ' -> ' + ok)
    return sorted(out)

for line in routes(spec):
    print(line)

