let calls = 0;
const flaky = async () => {
  calls++;
  if (calls < 3) throw new Error('fail ' + calls);
  return 'ok after ' + calls;
};
async function retry(fn, times) {
  for (let i = 0; i < times; i++) {
    try {
      return await fn();
    } catch (e) {
      console.log('attempt ' + (i + 1) + ' failed: ' + e.message);
      if (i === times - 1) throw e;
    }
  }
}
