function parse(url) {
  const [path, qs = ''] = url.split('?');
  const parts = path.split('/').filter(Boolean);
  const query = {};
  if (qs) {
    for (const kv of qs.split('&')) {
      const [k, v] = kv.split('=');
      query[k] = v;
    }
  }
  return { parts, query };
}
