function run(mws, errMw, req) {
  let i = 0;
  const next = (err) => {
    if (err) return errMw(err, req);
    const m = mws[i++];
    if (!m) return;
    try {
      m(req, next);
    } catch (e) {
      next(e);
    }
  };
  next();
}
run([
  (req, next) => { console.log('one'); next(); },
  (req, next) => { throw new Error('db down'); },
  (req, next) => { console.log('never'); }
], (err, req) => console.log('500 ' + err.message), {});

