from functools import wraps

def require(role):
    def deco(fn):
        @wraps(fn)
        def wrapper(user, *a, **k):
            if role not in user['roles']:
                raise PermissionError(role)
            return fn(user, *a, **k)
        return wrapper
    return deco

@require('admin')
def delete_user(user, uid):
    return 'deleted ' + str(uid)

