class InMemoryRepo:
    def __init__(self):
        self._items = {}
        self._next = 1

    def add(self, item):
        i = self._next
        self._items[i] = item
        self._next += 1
        return i

    def get(self, id):
        return self._items.get(id)

    def all(self):
        return [self._items[k] for k in sorted(self._items)]

r = InMemoryRepo()
print(r.add('pen'), r.add('book'))
print(r.get(2), r.get(9))
print(r.all())

