ALPHA = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'

def encode(n):
    if n == 0:
        return ALPHA[0]
    out = []
    while n:
        n, rem = divmod(n, 62)
        out.append(ALPHA[rem])
    return ''.join(reversed(out))

def decode(s):
    n = 0
    for ch in s:
        n = n * 62 + ALPHA.index(ch)
    return n

print(encode(0), encode(61), encode(62), encode(125))
big = 62 ** 7 - 1
print(encode(big), decode(encode(big)) == big)
print(62 ** 7)

jobs = [5, 1, 1, 1, 1, 1, 5, 1]

def round_robin(jobs, n=2):
    load = [0] * n
    for i, d in enumerate(jobs):
        load[i % n] += d
    return load

def least_loaded(jobs, n=2):
    load = [0] * n
    for d in jobs:
        load[load.index(min(load))] += d
    return load

print(round_robin(jobs))
print(least_loaded(jobs))

