def series(*a):
    p = 1.0
    for x in a:
        p *= x
    return p

def parallel(*a):
    f = 1.0
    for x in a:
        f *= (1 - x)
    return 1 - f

def downtime_min(a):
    return (1 - a) * 525600

print(round(series(0.999, 0.999, 0.999) * 100, 4))
