calls = {}
cache = {'value': None, 'at': None}
db_calls = 0

def heavy_report():
    return 'report-v' + str(db_calls)

def handle(client, now):
    global db_calls
    recent = [t for t in calls.get(client, []) if t > now - 60]
    if len(recent) >= 5:
        calls[client] = recent
        return (429, None)
    recent.append(now)
    calls[client] = recent
    if cache['at'] is None or now - cache['at'] >= 60:
        db_calls += 1
        cache['value'] = heavy_report()
        cache['at'] = now
    return (200, cache['value'])

results = []
for client, t in [('a', 0), ('a', 1), ('a', 2), ('a', 3), ('a', 4), ('a', 5), ('b', 30), ('a', 70)]:
    results.append(handle(client, t))
print(results)
print(db_calls)

import re

def slugify(s):
    return re.sub(r'[^a-z0-9]+', '-', s.lower()).strip('-')

cases = [('Hello World', 'hello-world'), ('  Rock & Roll!! ', 'rock-roll'), ('A--B', 'a-b'), ('', ''), ('Python 3.12', 'python-3-12')]
for given, want in cases:
    got = slugify(given)
    print('PASS' if got == want else 'FAIL', repr(given), '->', repr(got))

