class Greeter:
    def __init__(self, clock):
        self.clock = clock

    def greet(self, name):
        h = self.clock()
        if h < 12:
            return 'Good morning, ' + name
        if h < 17:
            return 'Good afternoon, ' + name
        return 'Good evening, ' + name

for hour in (9, 12, 16, 17, 23):
    print(hour, Greeter(lambda h=hour: h).greet('Asha'))

