class Cart:
    def __init__(self):
        self.lines = {}

    def add(self, name, price, qty=1):
        old = self.lines.get(name, (price, 0))
        self.lines[name] = (price, old[1] + qty)

    def remove(self, name):
        self.lines.pop(name, None)

    def total(self):
        return sum(p * q for p, q in self.lines.values())

    def count(self):
        return sum(q for p, q in self.lines.values())

c = Cart()
print(c.total() == 0)
