from itertools import product

def buggy_sort(xs):
    return sorted(set(xs))

def check(fn):
    bad = {'length': 0, 'ascending': 0, 'permutation': 0}
    for n in range(4):
        for t in product(range(3), repeat=n):
            xs = list(t)
            out = fn(xs)
            if len(out) != len(xs):
                bad['length'] += 1
            if any(out[i] > out[i + 1] for i in range(len(out) - 1)):
                bad['ascending'] += 1
            if sorted(out) != sorted(xs):
                bad['permutation'] += 1
    return bad

print(check(buggy_sort))
print(check(sorted))

