function reducer(state, action) {
  switch (action.type) {
    case 'add': return { ...state, count: state.count + action.qty };
    case 'clear': return { ...state, count: 0 };
    default: return state;
  }
}
let s = { count: 0, user: 'Asha' };
s = reducer(s, { type: 'add', qty: 2 });
s = reducer(s, { type: 'add', qty: 3 });
console.log(JSON.stringify(s));
