function createStore(reducer, initial) {
  let state = initial;
  const subs = [];
  return {
    getState: () => state,
    subscribe: (fn) => { subs.push(fn); },
    dispatch: (a) => {
      state = reducer(state, a);
      subs.forEach(fn => fn(state));
    }
  };
}
