function signal(v) {
  const subs = new Set();
  return {
    get() {
      if (active) subs.add(active);
      return v;
    },
    set(n) {
      if (n !== v) {
        v = n;
        subs.forEach(fn => fn());
      }
    }
  };
}
function effect(fn) {
  const run = () => {
    active = run;
    fn();
    active = null;
  };
