import re

def decide(cache_control, age, has_etag):
    if 'no-store' in cache_control:
        return 'fetch'
    m = re.search(r'max-age=(\d+)', cache_control)
    if m and age < int(m.group(1)) and 'no-cache' not in cache_control:
        return 'cache hit'
    return 'revalidate' if has_etag else 'fetch'

cases = [('max-age=600', 100, True), ('max-age=600', 700, True), ('max-age=600', 700, False), ('no-cache', 5, True), ('no-store', 5, True)]
for c in cases:
