def over_budget(resources, budgets):
    sums = {}
    for t, kb in resources:
        sums[t] = sums.get(t, 0) + kb
    sums['total'] = sum(kb for _, kb in resources)
    out = []
    for k, limit in budgets.items():
        if sums.get(k, 0) > limit:
            out.append(k + ' over by ' + str(sums[k] - limit) + ' KB')
    return sorted(out)

for line in over_budget(resources, budgets):
