import base64, json, hmac, hashlib

def b64(b):
    return base64.urlsafe_b64encode(b).rstrip(b'=').decode()

def unb64(s):
    return base64.urlsafe_b64decode(s + '=' * (-len(s) % 4))

def make(header, payload, secret):
    h = b64(json.dumps(header, separators=(',', ':')).encode())
    p = b64(json.dumps(payload, separators=(',', ':')).encode())
    sig = b64(hmac.new(secret.encode(), (h + '.' + p).encode(), hashlib.sha256).digest())
    return h + '.' + p + '.' + sig

def check(tok, secret, now):
    parts = tok.split('.')
    if len(parts) != 3:
        return 'malformed'
    h, p, s = parts
    header = json.loads(unb64(h))
    if header.get('alg') != 'HS256':
        return 'bad alg'
    want = b64(hmac.new(secret.encode(), (h + '.' + p).encode(), hashlib.sha256).digest())
    if not hmac.compare_digest(want, s):
        return 'bad signature'
    claims = json.loads(unb64(p))
    if claims['exp'] <= now:
        return 'expired'
    return 'ok:' + claims['sub']

S = 'demo-secret'
good = make({'alg': 'HS256', 'typ': 'JWT'}, {'sub': 'asha', 'exp': 2000}, S)
old = make({'alg': 'HS256', 'typ': 'JWT'}, {'sub': 'asha', 'exp': 900}, S)
none = make({'alg': 'none', 'typ': 'JWT'}, {'sub': 'admin', 'exp': 2000}, S)
h, p, s = good.split('.')
forged = h + '.' + b64(json.dumps({'sub': 'admin', 'exp': 2000}, separators=(',', ':')).encode()) + '.' + s
for t in (good, old, none, forged, 'abc'):
    print(check(t, S, 1000))

